function validate([graph, initial]) {
  const n = graph.length;
  if (n < 2 || n > 300) return 'graph needs 2 to 300 nodes.';
  for (let i = 0; i < n; i++) {
    if (!Array.isArray(graph[i]) || graph[i].length !== n) return 'graph must be a square n x n matrix.';
    if (graph[i][i] !== 1) return 'Every node must link to itself (graph[i][i] == 1).';
    for (let j = 0; j < n; j++) {
      if (graph[i][j] !== 0 && graph[i][j] !== 1) return 'graph entries are 0 or 1.';
      if (j < i && graph[i][j] !== graph[j][i]) return 'graph must be symmetric.';
    }
  }
  if (initial.length < 1 || initial.length > n) return 'initial needs 1 to n nodes.';
  if (initial.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each initial node is between 0 and n - 1.';
  if (new Set(initial).size !== initial.length) return 'initial nodes must be distinct.';
  return null;
}

