function minMalwareSpread(graph, initial) {
  const n = graph.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const size = new Array(n).fill(1);

  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (graph[i][j] === 1) {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
          parent[rootI] = rootJ;
          size[rootJ] += size[rootI];
        }
      }
    }
  }

  const infectedCount = new Array(n).fill(0);
  for (const node of initial) {
    infectedCount[find(node)]++;
  }

  let answer = Math.min(...initial);
  let bestSaved = 0;
  for (const node of initial) {
    const root = find(node);
    if (infectedCount[root] === 1) {
      const saved = size[root];
      if (saved > bestSaved || (saved === bestSaved && node < answer)) {
        bestSaved = saved;
        answer = node;
      }
    }
  }
  return answer;
}

