function minMalwareSpread(graph, initial) {
  // Simulate the spread for every possible removal and keep the best one.
  const n = graph.length;
  const spread = (sources) => {
    const infected = new Array(n).fill(false);
    const stack = [...sources];
    for (const s of sources) infected[s] = true;
    while (stack.length) {
      const u = stack.pop();
      for (let v = 0; v < n; v++) {
        if (graph[u][v] === 1 && !infected[v]) { infected[v] = true; stack.push(v); }
      }
    }
    return infected.filter(Boolean).length;
  };
  let best = -1;
  let bestCount = Infinity;
  for (const removed of initial) {
    const count = spread(initial.filter(x => x !== removed));
    if (count < bestCount || (count === bestCount && removed < best)) {
      bestCount = count;
      best = removed;
    }
  }
  return best;
}

