function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(80, 100) : int(2, 8);
  // Random relabelling so components are not made of consecutive indices.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const graph = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
  const link = (a, b) => { graph[label[a]][label[b]] = 1; graph[label[b]][label[a]] = 1; };
  // Split the nodes into groups and connect each group with a random tree plus a few extra links.
  const maxGroup = size === 'large' ? int(3, 25) : int(1, 4);
  for (let start = 0; start < n; ) {
    const len = Math.min(n - start, int(1, maxGroup));
    for (let i = 1; i < len; i++) link(start + i, start + int(0, i - 1));
    const extra = Math.floor(rand() * len);
    for (let e = 0; e < extra; e++) link(start + int(0, len - 1), start + int(0, len - 1));
    start += len;
  }
  // Occasionally add a few random links across groups.
  if (rand() < 0.3) {
    const cross = int(1, size === 'large' ? 5 : 2);
    for (let e = 0; e < cross; e++) link(int(0, n - 1), int(0, n - 1));
  }
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const k = size === 'large' ? int(1, 40) : int(1, n);
  return [graph, order.slice(0, k)];
}
